import httpStatus from "http-status";

import { prisma } from "../../lib/prisma.js";
import { AppError } from "../../utils/AppError.js";
import type { IRequestUser } from "../auth/auth.interface.js";

interface ICreateDonationPayload {
	amount: number;
	requestId: string;
}

const createDonation = async (
	payload: ICreateDonationPayload,
	user: IRequestUser,
) => {
	// Check authenticated user
	const donorUser = await prisma.user.findUnique({
		where: {
			id: user.userId,
		},
	});

	if (!donorUser) {
		throw new AppError(httpStatus.NOT_FOUND, "User not found");
	}

	// Only DONOR can create donation
	if (donorUser.role !== "DONOR") {
		throw new AppError(httpStatus.FORBIDDEN, "Only donors can make donations");
	}

	// Check blocked or deleted user
	if (
		donorUser.isDeleted ||
		donorUser.status === "DELETED" ||
		donorUser.status === "BLOCKED"
	) {
		throw new AppError(
			httpStatus.FORBIDDEN,
			"Your account is not allowed to make donations",
		);
	}

	// Validate donation amount
	if (payload.amount <= 0) {
		throw new AppError(
			httpStatus.BAD_REQUEST,
			"Donation amount must be greater than 0",
		);
	}

	// Check donation request
	const donationRequest = await prisma.donationRequest.findUnique({
		where: {
			id: payload.requestId,
		},
	});

	if (!donationRequest) {
		throw new AppError(httpStatus.NOT_FOUND, "Donation request not found");
	}

	// Donor can only donate to verified requests
	if (donationRequest.status !== "VERIFIED") {
		throw new AppError(
			httpStatus.BAD_REQUEST,
			"Donation can only be made to a verified request",
		);
	}

	// Create donation
	const donation = await prisma.donation.create({
		data: {
			amount: payload.amount,
			donorId: user.userId,
			requestId: payload.requestId,
			status: "PENDING",
			paymentStatus: "PENDING",
		},
	});

	return donation;
};

const getMyDonations = async (user: IRequestUser) => {
	const donorUser = await prisma.user.findUnique({
		where: {
			id: user.userId,
		},
	});

	if (!donorUser) {
		throw new AppError(httpStatus.NOT_FOUND, "User not found");
	}

	if (donorUser.role !== "DONOR") {
		throw new AppError(
			httpStatus.FORBIDDEN,
			"Only donors can view donation history",
		);
	}

	if (
		donorUser.isDeleted ||
		donorUser.status === "DELETED" ||
		donorUser.status === "BLOCKED"
	) {
		throw new AppError(
			httpStatus.FORBIDDEN,
			"Your account is not allowed to view donation history",
		);
	}

	const donations = await prisma.donation.findMany({
		where: {
			donorId: user.userId,
		},
		include: {
			request: {
				select: {
					id: true,
					title: true,
					description: true,
					requiredAmount: true,
					status: true,
					situationVideo: true,
					situationAudio: true,
				},
			},
		},
		orderBy: {
			createdAt: "desc",
		},
	});

	return donations;
};

const getReceivedDonations = async (user: IRequestUser) => {
  const needyUser = await prisma.user.findUnique({
    where: {
      id: user.userId,
    },
  });

  if (!needyUser) {
    throw new AppError(httpStatus.NOT_FOUND, "User not found");
  }

  if (needyUser.role !== "NEEDY") {
    throw new AppError(
      httpStatus.FORBIDDEN,
      "Only needy users can view received donations",
    );
  }

  if (
    needyUser.isDeleted ||
    needyUser.status === "DELETED" ||
    needyUser.status === "BLOCKED"
  ) {
    throw new AppError(
      httpStatus.FORBIDDEN,
      "Your account is not allowed to view received donations",
    );
  }

  const donations = await prisma.donation.findMany({
    where: {
      request: {
        needyId: user.userId,
      },
      status: "COMPLETED",
    },
    include: {
      request: {
        select: {
          id: true,
          title: true,
        },
      },
      donor: {
        select: {
          id: true,
          name: true,
          imageUrl: true,
        },
      },
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  const totalReceived = donations.reduce(
    (total, donation) => total + Number(donation.amount),
    0,
  );

  return {
    totalReceived,
    donations,
  };
};

export const DonationService = {
	createDonation,
	getMyDonations,
	getReceivedDonations
};
